package com.profa.messaging;import org.springframework.messaging.handler.annotation.*;import org.springframework.messaging.simp.SimpMessagingTemplate;import org.springframework.stereotype.Controller;@Controller public class ChatSocketController{final SimpMessagingTemplate t;public ChatSocketController(SimpMessagingTemplate t){this.t=t;}@MessageMapping("/chat.send")public void send(ChatMessage m){t.convertAndSend("/topic/conversation/"+m.conversationId(),m);}public record ChatMessage(String conversationId,String senderId,String body) {}}